export const TEAM_AGREEMENTS_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu kesepakatan tim",q:"'Kesepakatan tim' (aturan bersama) adalah...",options:["Sekumpulan aturan & cara kerja yang disepakati semua anggota di awal, untuk memandu bagaimana tim bekerja bersama","Aturan yang dibuat ketua lalu dipaksakan kepada anggota tanpa dibahas dulu, sehingga anggota hanya bisa mengikutinya","Daftar hukuman yang disiapkan untuk anggota yang malas, supaya anggota takut dan tidak berani melanggar aturan tim"],answer:0,explain:"Kesepakatan tim bukan perintah — ia dibuat bersama & mengikat semua, termasuk ketua.",hint:"Disepakati bersama, atau dipaksakan ketua?"},
{n:2,type:"mcq",micro:"Kenapa perlu kesepakatan",q:"Tim yang membuat kesepakatan di awal cenderung...",options:["Lebih sering berdebat karena terlalu banyak aturan yang harus diingat oleh anggota","Punya lebih sedikit konflik & kebingungan, karena 'aturan main' sudah jelas sebelum masalah muncul","Lebih lambat bekerja, karena banyak waktu terbuang untuk membahas aturan yang kurang diperlukan"],answer:1,explain:"Menyepakati cara kerja saat semua masih tenang jauh lebih mudah daripada saat sudah ada masalah.",hint:"Lebih sedikit konflik, atau lebih ribet?"},
{n:3,type:"mcq",micro:"Isi kesepakatan: komunikasi",q:"Salah satu hal yang perlu disepakati tim di awal:",options:["Warna favorit & makanan kesukaan tiap anggota, supaya suasana rapat menyenangkan sejak awal","Siapa anggota yang paling pintar, supaya ia bisa dipilih menjadi penentu keputusan tim sejak awal","Lewat mana kita berkomunikasi (grup chat mana), seberapa sering cek, & berapa lama batas wajar membalas"],answer:2,explain:"Kesepakatan komunikasi mencegah 'kok kamu nggak bales?' & info yang tercecer di banyak tempat.",hint:"Cara & ritme komunikasi, atau warna favorit?"},
{n:4,type:"mcq",micro:"Isi kesepakatan: tenggat",q:"Kesepakatan soal tenggat yang baik:",options:["Tenggat internal beberapa hari sebelum tenggat asli, supaya ada waktu menggabungkan & memperbaiki","Semua bagian dikumpulkan tepat pada tenggat asli dari guru, tanpa tenggat tambahan di dalam tim","Tidak perlu tenggat; kerjakan dengan santai sampai selesai karena yang dicari hanya hasil yang bagus"],answer:0,explain:"Tenggat internal memberi bantalan. Mengumpulkan semua di detik terakhir tidak menyisakan waktu untuk kesalahan.",hint:"Tenggat internal lebih awal, atau tepat di batas / tanpa tenggat?"},
{n:5,type:"mcq",micro:"Isi kesepakatan: bila ada kendala",q:"Kesepakatan penting soal kendala:",options:["Kendala adalah urusan pribadi masing-masing anggota, jadi cukup diselesaikan sendiri tanpa dibahas dengan tim","Wajib mengabari tim secepatnya bila ada risiko tidak bisa menyelesaikan bagian — tidak boleh menghilang mendadak","Boleh diam dulu sampai ketahuan oleh tim, karena melapor kendala bisa membuat anggota lain kecewa dan kehilangan semangat"],answer:1,explain:"Kendala yang dikabarkan lebih awal bisa dibantu tim. Yang disembunyikan meledak di akhir.",hint:"Kabari secepatnya, atau diam sampai ketahuan?"},
{n:6,type:"mcq",micro:"Kesepakatan mengikat semua",q:"Aturan tim yang disepakati bersama berlaku untuk...",options:["Hanya anggota biasa; ketua dan koordinator bebas","Hanya anggota yang setuju saat rapat tadi","Semua anggota, termasuk ketua/koordinator"],answer:2,explain:"Kesepakatan kehilangan kekuatannya kalau sebagian orang (apalagi ketua) merasa dikecualikan.",hint:"Semua termasuk ketua, atau ketua bebas?"},
{n:7,type:"mcq",micro:"Membuat kesepakatan bersama",q:"Cara membuat kesepakatan tim yang benar-benar dipatuhi:",options:["Buat bersama-sama dengan masukan tiap anggota, lalu semua menyetujui secara sadar","Ketua menulis sendiri semua aturan lalu memberi tahu anggota tanpa meminta pendapat mereka","Salin saja aturan dari kelompok lain yang sudah berhasil tanpa dibahas dulu dengan tim"],answer:0,explain:"Orang mematuhi aturan yang ikut mereka buat. Aturan yang dipaksakan sering diabaikan.",hint:"Dibuat bersama, atau ditulis ketua / disalin?"},
{n:8,type:"mcq",micro:"Kesepakatan soal rapat",q:"Kesepakatan tentang pertemuan yang membantu:",options:["Rapat dilakukan sewaktu-waktu saja, tergantung siapa yang sempat","Kapan & di mana rapat, durasi maksimal, & datang tepat waktu","Rapat hanya di rumah ketua, dengan durasi sesuka anggota yang hadir"],answer:1,explain:"Rapat yang terjadwal & tepat waktu menghormati waktu semua & memastikan koordinasi rutin.",hint:"Terjadwal + tepat waktu, atau kapan saja / tidak pernah?"},
{n:9,type:"order",micro:"Menyusun kesepakatan tim",q:"Urutkan langkah menyusun kesepakatan tim di pertemuan pertama.",items:["Sepakati tujuan proyek & standar hasil yang diinginkan","Bahas & sepakati cara komunikasi, jadwal rapat, & tenggat internal","Bahas & sepakati aturan bila ada kendala & cara menyelesaikan ketidaksepakatan","Tuliskan semua kesepakatan & minta tiap anggota menyetujui"],answer:[0,1,2,3],explain:"Tujuan → komunikasi & jadwal → aturan kendala & konflik → tulis & sepakati. Semua tertulis di satu tempat.",hint:"Apa yang disepakati paling dasar dulu?"},
{n:10,type:"mcq",micro:"Kesepakatan tertulis",q:"Menuliskan kesepakatan tim (bukan hanya menyepakatinya lisan) berguna karena...",options:["Membuat tim terlalu formal dan kaku dalam bekerja sehari-hari","Tidak ada gunanya, karena anggota biasanya sudah mengingat semuanya sendiri","Menjadi acuan bersama yang bisa dirujuk bila ada yang lupa atau berbeda ingatan"],answer:2,explain:"Ingatan lisan mudah berbeda antar orang. Catatan tertulis menghentikan perdebatan 'kita kan sepakat...'.",hint:"Acuan yang bisa dirujuk, atau terlalu formal?"},
{n:11,type:"tf",micro:"Kesepakatan sebelum masalah",q:"Benar atau Salah: Lebih mudah menyepakati aturan tim saat semua masih tenang di awal, daripada mencoba membuat aturan saat konflik sudah terjadi.",answer:true,explain:"Saat konflik, emosi tinggi & orang cenderung membuat aturan yang menguntungkan pihaknya. Di awal, semua lebih objektif.",hint:"Di awal saat tenang, atau saat konflik?"},
{n:12,type:"tf",micro:"Kesepakatan = perintah ketua?",q:"Benar atau Salah: Kesepakatan tim yang baik adalah yang ditulis sendiri oleh ketua & diberitahukan ke anggota untuk dipatuhi.",answer:false,explain:"Sebaliknya, kesepakatan yang efektif dibuat BERSAMA dengan masukan semua anggota, sehingga mereka merasa ikut memiliki & lebih patuh.",hint:"Ditulis ketua sendiri, atau dibuat bersama?"},
{n:13,type:"mcq",micro:"Kesepakatan soal keputusan",q:"Kesepakatan tentang cara mengambil keputusan tim:",options:["Sepakati di awal: keputusan besar lewat diskusi + voting/kompromi; keputusan mendesak boleh diambil koordinator lalu dijelaskan","Setiap keputusan, kecil maupun besar, harus disetujui bulat oleh seluruh anggota, dan bila satu orang menolak, keputusan tidak dijalankan","Tidak perlu disepakati sebelumnya; putuskan saja saat masalah muncul dengan cara yang paling cepat pada saat itu"],answer:0,explain:"Menyepakati mekanisme keputusan mencegah kebuntuan & 'kenapa kamu putusin sendiri?' di kemudian hari.",hint:"Mekanisme disepakati di awal, atau bulat 100% / dadakan?"},
{n:14,type:"mcq",micro:"Kesepakatan soal saling menghormati",q:"Aturan dasar tentang cara berinteraksi dalam tim:",options:["Tidak ada aturan khusus; masing-masing anggota bebas bicara dan bersikap sesuai kemauannya","Bicara bergantian tanpa menghina, dengarkan pendapat berbeda, kritik ide bukan pribadi","Yang suaranya paling keras yang diikuti, sedangkan anggota pendiam sebaiknya mengikuti saja pendapat itu"],answer:1,explain:"Menyepakati 'aturan main percakapan' membuat diskusi tetap aman & produktif meski ada perbedaan.",hint:"Bergantian + hormat + kritik ide, atau siapa keras menang?"},
{n:15,type:"mcq",micro:"Meninjau kesepakatan",q:"Kalau sebuah kesepakatan tim ternyata tidak berjalan (mis. rapat tiap hari terlalu sering), sebaiknya...",options:["Paksakan saja meski tidak berjalan, karena aturan sudah ditetapkan","Abaikan diam-diam tanpa memberi tahu anggota yang lain","Bahas bersama & sesuaikan — kesepakatan bisa direvisi bila tim setuju"],answer:2,explain:"Kesepakatan melayani tim. Bila tidak cocok, revisi bersama — bukan dipaksakan atau diabaikan sepihak.",hint:"Revisi bersama, atau paksakan / abaikan?"},
{n:16,type:"mcq",micro:"Kesepakatan & anggota baru",q:"Ketika anggota baru bergabung, hal yang perlu dilakukan soal kesepakatan tim:",options:["Jelaskan kesepakatan yang sudah ada & beri ia kesempatan bertanya atau mengusulkan perubahan","Biarkan ia melanggar dulu karena belum tahu, lalu tegur setelah ia melakukan kesalahan yang cukup besar","Ganti kesepakatan lama dengan buatan anggota baru itu, supaya ia merasa dihargai sebagai bagian tim"],answer:0,explain:"Anggota baru perlu tahu 'aturan main' & sebaiknya diberi ruang kecil untuk menyesuaikannya.",hint:"Jelaskan + beri ruang usul, atau biarkan / ganti semua?"},
{n:17,type:"mcq",micro:"Kesepakatan soal konsekuensi",q:"Kesepakatan yang menyebut 'apa yang terjadi bila aturan dilanggar':",options:["Tidak perlu disebutkan, sebab anggota tim biasanya patuh dengan sendirinya dan jarang ada yang melanggar","Membantu — semua tahu batas & konsekuensinya sejak awal, bukan kejutan atau perlakuan tidak adil","Membuat tim terasa seperti penjara, sehingga anggota tertekan dan tidak berani bekerja dengan nyaman"],answer:1,explain:"Konsekuensi yang disepakati di awal (mis. 'telat 2x tanpa kabar → dibahas dengan guru') adil karena semua tahu sebelumnya.",hint:"Batas & konsekuensi jelas di awal, atau tanpa / kejutan?"},
{n:18,type:"mcq",micro:"Kesepakatan yang realistis",q:"Kesepakatan tim sebaiknya...",options:["Sangat ketat dengan kewajiban harian, walaupun banyak anggota kesulitan memenuhinya","Sangat longgar sampai tidak berarti, sehingga anggota boleh melanggar tanpa konsekuensi","Realistis & bisa dijalankan semua anggota (mis. cek 2 hari sekali, bukan tiap jam)"],answer:2,explain:"Aturan yang tidak mungkin dipatuhi akan diabaikan & membuat kesepakatan lain ikut kehilangan wibawa.",hint:"Realistis, atau terlalu ketat / longgar?"},
{n:19,type:"mcq",micro:"Kesepakatan menjaga semua",q:"Kesepakatan tim yang baik melindungi...",options:["Semua anggota — dari beban tidak adil, dari perlakuan tidak hormat, & dari kejutan buruk","Hanya anggota yang rajin, karena yang malas memang sudah layak menanggung akibatnya","Hanya ketua, karena dialah yang memikul tanggung jawab atas hasil kerja tim"],answer:0,explain:"Kesepakatan yang adil menjaga tiap orang, termasuk yang mungkin kesulitan atau berbeda pendapat.",hint:"Semua anggota, atau hanya sebagian?"},
{n:20,type:"open",micro:"Menyusun kesepakatan tim",q:"Kamu & 4 teman akan mengerjakan proyek 3 minggu. Tulis 'kesepakatan tim' berisi minimal 6 poin yang akan kalian sepakati di pertemuan pertama, dengan alasan tiap poin.",explain:"Jawaban baik memuat minimal 6 poin dengan alasan, mencakup: tujuan/standar, komunikasi (cara+ritme+batas balas), rapat (jadwal+durasi+kehadiran), pembagian tugas + tenggat internal, aturan kendala, mekanisme keputusan, cara berinteraksi/hormat, konsekuensi pelanggaran, & klausul revisi.",hint:"Turunkan tiap area jadi aturan konkret: tujuan, komunikasi, rapat, tugas+tenggat, kendala, keputusan, interaksi, konsekuensi, revisi.",sample:"Kesepakatan tim: (1) Tujuan & standar: kami menghasilkan [hasil] yang lengkap, rapi, dan dikumpulkan tepat waktu. Alasan: semua menuju arah yang sama. (2) Komunikasi: lewat grup chat khusus proyek; wajib cek minimal sekali sehari; balas hal penting dalam 12 jam. Alasan: info tidak tercecer & masalah cepat ketahuan. (3) Rapat: setiap Rabu & Sabtu, maksimal 30 menit, datang tepat waktu; yang berhalangan wajib memberi tahu & membaca notulen. Alasan: koordinasi rutin tanpa membuang waktu. (4) Pembagian tugas & tenggat: tiap orang pegang satu bagian sesuai kekuatan, tertulis dengan tenggat internal 3 hari sebelum tenggat asli. Alasan: beban jelas & ada waktu menggabungkan. (5) Bila ada kendala: wajib mengabari tim minimal 1 hari sebelum tenggat bagian, tidak boleh menghilang. Alasan: tim bisa membantu atau menyesuaikan. (6) Keputusan: hal besar dibahas & diputuskan lewat suara terbanyak/kompromi; hal mendesak boleh diputuskan koordinator lalu dijelaskan; setelah diputuskan semua mendukung. Alasan: mencegah kebuntuan & 'kenapa kamu putusin sendiri'. (7) Cara berinteraksi: bicara bergantian, dengarkan pendapat berbeda, kritik ide bukan pribadi. Alasan: diskusi tetap aman. (8) Bila aturan dilanggar (mis. telat tanpa kabar 2x): dibahas dulu berdua, lalu di tim, lalu bila perlu dengan guru berdasarkan fakta. Alasan: konsekuensi adil & tidak mendadak. (9) Kesepakatan ini bisa direvisi bila tim setuju."},
{n:21,type:"classify",micro:"Kesepakatan jelas vs kabur",q:"Kelompokkan tiap 'aturan tim' ke 'Jelas & bisa dijalankan' atau 'Kabur / sulit dijalankan'.",items:["'Cek grup chat minimal sekali sehari, balas hal penting dalam 12 jam'","'Semua harus rajin & bertanggung jawab'","'Tenggat internal: bagian selesai 3 hari sebelum batas'","'Jangan malas'"],groups:["Jelas & bisa dijalankan","Kabur / sulit dijalankan"],answer:{"Jelas & bisa dijalankan":["'Cek grup chat minimal sekali sehari, balas hal penting dalam 12 jam'","'Tenggat internal: bagian selesai 3 hari sebelum batas'"],"Kabur / sulit dijalankan":["'Semua harus rajin & bertanggung jawab'","'Jangan malas'"]},explain:"Aturan yang baik menyebut perilaku spesifik yang bisa diamati ('cek sekali sehari'). 'Rajin' & 'jangan malas' tidak bisa diukur & mudah diperdebatkan.",hint:"Bisa diukur/diamati, atau sekadar sikap kabur?"},
{n:22,type:"mcq",micro:"Aturan spesifik vs sikap umum",q:"Mengapa 'cek chat sekali sehari' lebih baik sebagai aturan daripada 'jadi anggota yang responsif'?",options:["Terdengar lebih ramah dan sopan, sehingga anggota merasa nyaman membacanya","Bisa diamati & disepakati bersama apakah dipenuhi; 'responsif' terlalu subjektif","Lebih pendek dan mudah diingat, sehingga bisa ditempel di dinding kelas"],answer:1,explain:"Aturan yang efektif menerjemahkan sikap ('responsif') jadi perilaku konkret ('cek sekali sehari').",hint:"Bisa diamati bersama, atau lebih pendek?"},
{n:23,type:"mcq",micro:"Kesepakatan & rasa memiliki",q:"Anggota yang ikut menyusun kesepakatan tim cenderung...",options:["Lebih sering melanggarnya, karena merasa aturan itu sudah dibuat dan tidak lagi perlu dijaga","Tidak peduli pada aturan itu, karena menganggap urusan menegakkan aturan hanya tugas ketua tim","Lebih mematuhinya & lebih berani mengingatkan anggota lain, karena itu 'aturan kita' bukan 'aturan ketua'"],answer:2,explain:"Kepemilikan lahir dari partisipasi. Aturan yang dipaksakan terasa asing & mudah diabaikan.",hint:"Lebih mematuhi, atau lebih melanggar?"},
{n:24,type:"mcq",micro:"Kesepakatan soal 'penumpang gelap'",q:"Kesepakatan yang membantu mencegah penumpang gelap:",options:["Pembagian tugas tertulis + tenggat internal + cek kemajuan rutin + langkah bila ada yang tidak mengerjakan bagiannya","Berharap semua anggota jujur dan bertanggung jawab dengan sendirinya, tanpa pembagian tugas tertulis atau cek kemajuan","Membiarkan anggota rajin menanggung pekerjaan yang tidak dikerjakan, karena mereka mampu dan tidak keberatan"],answer:0,explain:"Struktur (tugas jelas + cek rutin + langkah eskalasi) membuat kontribusi terpantau & penumpang gelap sulit bersembunyi.",hint:"Struktur + langkah eskalasi, atau berharap / membiarkan?"},
{n:25,type:"mcq",micro:"Meninjau kesepakatan di tengah jalan",q:"Kapan kesepakatan tim sebaiknya ditinjau ulang?",options:["Setiap hari, supaya tim terus memperbarui aturan sebelum sempat dijalankan dengan baik","Bila jelas tidak berjalan, bila situasi berubah, atau di titik tengah proyek sebagai cek rutin","Tidak perlu ditinjau lagi; kesepakatan awal bersifat mutlak dan tidak boleh diubah"],answer:1,explain:"Kesepakatan adalah alat hidup. Tinjau saat ada tanda tidak cocok atau di titik tengah, bukan tidak pernah atau terus-menerus.",hint:"Saat tidak berjalan / titik tengah, atau tidak pernah / tiap hari?"},
{n:26,type:"mcq",micro:"Kesepakatan yang adil untuk semua",q:"Saat menyusun aturan, penting mempertimbangkan...",options:["Hanya kenyamanan anggota yang paling vokal dan paling sering bicara, karena merekalah yang paling tahu kebutuhan tim","Membuat aturan sesulit mungkin supaya anggota terpacu bekerja keras dan takut bermalas-malasan di dalam tim","Apakah aturan ini bisa dipenuhi anggota dengan situasi berbeda (mis. yang tidak punya internet di rumah, yang sibuk kegiatan lain)"],answer:2,explain:"Aturan yang hanya cocok untuk sebagian anggota tidak adil & akan dilanggar oleh yang lain.",hint:"Bisa dipenuhi semua situasi, atau hanya sebagian?"},
{n:27,type:"tf",micro:"Kesepakatan mengurangi konflik",q:"Benar atau Salah: Tim yang menyepakati cara menyelesaikan ketidaksepakatan di awal justru lebih sering berkonflik, karena mereka jadi terlalu fokus pada prosedur.",answer:false,explain:"Sebaliknya, saat konflik muncul, tim yang punya 'prosedur' (mis. 'dengar semua lalu voting') tinggal menjalankannya dengan tenang. Tim tanpa prosedur ikut berkonflik soal cara menyelesaikan konflik.",hint:"Punya prosedur disepakati, atau tidak?"},
{n:28,type:"tf",micro:"Kesepakatan terlalu banyak aturan",q:"Benar atau Salah: Semakin banyak & detail aturan dalam kesepakatan tim, semakin baik & semakin lancar tim bekerja.",answer:false,explain:"Sebaliknya, terlalu banyak aturan sulit diingat & dipatuhi, serta membuat tim kaku. Beberapa aturan inti yang jelas & disepakati lebih efektif.",hint:"Makin banyak aturan makin baik, atau beberapa aturan inti cukup?"},
{n:29,type:"mcq",micro:"Kesepakatan soal alat & dokumen",q:"Kesepakatan praktis yang sering terlupa tapi penting:",options:["Di mana file & dokumen bersama disimpan, siapa yang bisa mengedit, & bagaimana penamaan file","Merek laptop dan ponsel tiap anggota, supaya mudah dicocokkan saat dokumen dibagikan","Warna dan jenis huruf dokumen, supaya tampilannya sama dan enak dilihat guru"],answer:0,explain:"File yang tersebar di banyak tempat dengan nama membingungkan ('Untitled(3)') membuang banyak waktu tim.",hint:"Lokasi & penamaan file bersama, atau merek laptop?"},
{n:30,type:"order",micro:"Menangani pelanggaran kesepakatan",q:"Urutkan langkah tim menghadapi anggota yang berulang kali melanggar kesepakatan (mis. tidak pernah ikut rapat).",items:["Ingatkan dengan sopan soal kesepakatan yang disetujui bersama","Bicara berdua untuk memahami kendalanya & cari solusi","Bawa ke pembahasan tim: dampaknya & apa yang dibutuhkan ke depan","Bila tidak ada perubahan & memengaruhi hasil, jalankan konsekuensi yang disepakati / libatkan guru berbasis fakta"],answer:[0,1,2,3],explain:"Ingatkan → bicara berdua → bahas di tim → konsekuensi/eskalasi. Berjenjang, memberi kesempatan, berbasis kesepakatan.",hint:"Apa langkah pertama sebelum membawa ke tim?"},
{n:31,type:"mcq",micro:"Kesepakatan vs fleksibilitas",q:"Kesepakatan tim tetap perlu menyisakan ruang untuk...",options:["Tidak ada pengecualian, sekaku mungkin, sekalipun anggota sedang sakit atau keluarganya mengalami keadaan darurat","Situasi tak terduga (anggota sakit, keadaan darurat) — dengan cara menanganinya yang juga disepakati","Anggota boleh melanggar kapan saja selama punya alasan sendiri, dan tidak perlu menjelaskan kepada tim"],answer:1,explain:"Aturan baik + prosedur untuk pengecualian yang sah = tim yang tegas sekaligus manusiawi.",hint:"Ruang untuk situasi tak terduga (dengan prosedur), atau kaku total / bebas melanggar?"},
{n:32,type:"tf",micro:"Kesepakatan berlaku sejak disepakati",q:"Benar atau Salah: Kesepakatan tim hanya berlaku bila ada guru atau pihak luar yang mengawasi; tanpa pengawasan, ia hanya wacana yang boleh diabaikan.",answer:false,explain:"Sebaliknya, kesepakatan mengikat semua anggota begitu disetujui. Menegakkannya (dengan cara yang disepakati) & menepatinya meski tak diawasi adalah bagian dari kesepakatan itu sendiri.",hint:"Mengikat setelah disepakati, atau hanya saat diawasi?"},
{n:33,type:"mcq",micro:"Kesepakatan & kepercayaan",q:"Hubungan antara menepati kesepakatan & kepercayaan tim:",options:["Tidak ada hubungannya, sebab kepercayaan tumbuh dari hal lain seperti kedekatan pribadi di luar kerja tim","Kesepakatan justru mengurangi kepercayaan, karena anggota merasa diawasi dan dibatasi geraknya","Setiap kali anggota menepati kesepakatan, kepercayaan tumbuh; setiap pelanggaran tanpa penjelasan mengikisnya"],answer:2,explain:"Kesepakatan yang ditepati adalah bukti berulang bahwa anggota bisa diandalkan.",hint:"Menepati = kepercayaan tumbuh, atau tak berhubungan?"},
{n:34,type:"mcq",micro:"Kesepakatan soal umpan balik",q:"Kesepakatan yang membuat pemberian umpan balik antar anggota lebih mudah:",options:["Sepakati bahwa umpan balik itu normal & disambut, disampaikan spesifik & sopan (kritik privat, apresiasi terbuka)","Larang kritik dan komentar tentang hasil kerja orang lain, supaya tidak ada yang tersinggung dan suasana tetap tenang","Umpan balik hanya boleh diberikan ketua, sedangkan anggota lain tidak boleh menilai sesama anggota"],answer:0,explain:"Menormalkan umpan balik di awal membuatnya terasa biasa, bukan serangan, saat benar-benar dibutuhkan.",hint:"Normalkan umpan balik yang sopan, atau larang / hanya ketua?"},
{n:35,type:"mcq",micro:"Kesepakatan realistis soal ketersediaan",q:"Sebelum menyepakati jadwal rapat & tenggat, tim sebaiknya...",options:["Berasumsi anggota bisa hadir kapan saja tanpa bertanya, karena tim yang baik mengutamakan proyek dulu","Bertanya ketersediaan tiap anggota (kegiatan lain, jam sibuk) & mencari waktu yang cocok untuk semua","Menetapkan jadwal sesuai kenyamanan ketua saja, dan anggota lain tinggal menyesuaikan diri"],answer:1,explain:"Jadwal yang tidak mempertimbangkan ketersediaan nyata akan sering dilanggar bukan karena malas tapi karena bentrok.",hint:"Cek ketersediaan semua, atau asumsi / ikut ketua?"},
{n:36,type:"mcq",micro:"Kesepakatan & keputusan yang sudah diambil",q:"Kesepakatan tentang keputusan yang sudah final:",options:["Anggota yang tidak setuju boleh mengabaikan keputusan itu dan mengerjakan bagiannya sesuka hati","Keputusan bisa dibatalkan oleh yang tidak puas, bahkan ketika pekerjaan sudah berjalan setengah jalan","Setelah tim memutuskan bersama, semua mendukung & tidak menyabotase — meski bukan pilihan pribadinya"],answer:2,explain:"'Tidak setuju & tetap komit' (disagree and commit) menjaga tim tetap bergerak setelah keputusan diambil.",hint:"Semua dukung setelah final, atau boleh diabaikan / dibatalkan?"},
{n:37,type:"tf",micro:"Kesepakatan untuk proyek kecil",q:"Benar atau Salah: Bahkan proyek kecil dengan tenggat pendek layak punya kesepakatan singkat (siapa - apa - kapan + cara komunikasi), karena biayanya kecil & mencegah banyak masalah.",answer:true,explain:"Kesepakatan tidak harus panjang. Untuk proyek kecil, beberapa baris sudah cukup & sangat berharga.",hint:"Proyek kecil butuh kesepakatan singkat, atau tidak perlu sama sekali?"},
{n:38,type:"mcq",micro:"Kesepakatan & anggota yang tidak hadir saat penyusunan",q:"Seorang anggota tidak hadir saat tim menyusun kesepakatan. Sikap yang adil:",options:["Bagikan kesepakatan itu padanya, jelaskan, & beri kesempatan mengusulkan perubahan sebelum dianggap final untuknya","Anggap dia otomatis terikat pada kesepakatan itu tanpa perlu diberi tahu, karena aturan berlaku bagi anggota","Buat aturan yang merugikannya karena ia absen saat rapat, supaya lain kali ia lebih disiplin"],answer:0,explain:"Kesepakatan mengikat karena disetujui. Anggota yang absen perlu diberi tahu & kesempatan menyuarakan pendapat.",hint:"Bagikan + beri ruang usul, atau ikat diam-diam / merugikan?"},
{n:39,type:"mcq",micro:"Kesepakatan soal pengakuan kontribusi",q:"Kesepakatan yang mencegah konflik soal 'siapa yang berjasa':",options:["Tidak membahas pengakuan di awal, karena urusan siapa berjasa akan terlihat dengan sendirinya di akhir","Sepakati bahwa kontribusi tiap orang dicatat & diakui, & hasil disampaikan sebagai kerja bersama","Biarkan yang presentasi mendapat pengakuan dari guru, karena dialah yang paling terlihat dan berani tampil"],answer:1,explain:"Kejelasan di awal soal bagaimana kontribusi diakui mencegah kekecewaan & perebutan jasa di akhir.",hint:"Sepakati pengakuan adil di awal, atau biarkan / abaikan?"},
{n:40,type:"open",micro:"Memperbaiki kesepakatan yang lemah",q:"Sebuah tim membuat 'kesepakatan': (1) semua harus rajin, (2) jangan telat, (3) kerja sama yang baik. Setelah seminggu, tim tetap kacau. Jelaskan mengapa kesepakatan ini lemah, lalu tulis ulang jadi 3-4 aturan yang lebih efektif.",explain:"Jawaban baik menjelaskan bahwa kesepakatan lama lemah karena berisi sikap kabur yang tidak terukur, tanpa perilaku spesifik/waktu/konsekuensi — lalu menulis ulang jadi 3-4 aturan konkret (perilaku spesifik + angka/waktu + siapa + apa yang terjadi bila dilanggar).",hint:"Tunjukkan 'rajin/telat/kerja sama' tidak terukur & tanpa konsekuensi; ubah jadi aturan dengan perilaku spesifik, waktu, penanggung jawab, konsekuensi.",sample:"Mengapa lemah: ketiga poin adalah SIKAP UMUM yang tidak bisa diukur atau disepakati bersama apakah dipenuhi. 'Rajin' menurut siapa? 'Telat' dari jam berapa, telat apa? 'Kerja sama yang baik' seperti apa bentuknya? Tidak ada satu pun yang menyebut perilaku spesifik, waktu, atau apa yang terjadi bila tidak dipenuhi. Jadi ketika ada masalah, tim tidak punya acuan konkret dan hanya bisa saling menuduh. Versi yang lebih efektif: (1) Komunikasi: cek grup chat minimal sekali sehari; balas pesan penting dalam 12 jam; kalau ada kendala di bagianmu, kabari tim minimal 1 hari sebelum tenggat bagian. (2) Tenggat: tiap bagian selesai 3 hari sebelum tenggat asli (tenggat internal), dicatat tertulis dengan nama penanggung jawab. (3) Rapat: setiap Selasa & Jumat jam 4 sore lewat video call, maksimal 25 menit, datang tepat waktu; yang berhalangan wajib memberi tahu sebelumnya dan membaca notulen. (4) Bila aturan dilanggar (mis. tidak ikut rapat atau telat tenggat tanpa kabar 2x): dibicarakan berdua dulu, lalu di tim, lalu bila memengaruhi hasil disampaikan ke guru berdasarkan catatan."},
{n:41,type:"mcq",micro:"Skenario: tim menolak membuat kesepakatan",q:"Anggota timmu berkata 'nggak usah ribet bikin aturan, langsung kerja aja'. Respons yang membujuk:",options:["Menyerah dan langsung kerja tanpa kesepakatan, karena membuat aturan terasa ribet dan masalah bisa dibahas nanti","Memaksa dengan marah: 'Pokoknya harus bikin aturan dulu! Kalau tidak mau, keluar saja dari kelompok!'","'15 menit aja buat sepakati siapa ngerjain apa, kapan, & lewat mana kita ngobrol. Ini justru bikin nggak ribet nanti.'"],answer:2,explain:"Bingkai kesepakatan sebagai penghemat waktu (bukan birokrasi) & buat singkat. Kebanyakan orang setuju bila cepat & jelas manfaatnya.",hint:"Bingkai sebagai penghemat waktu + singkat, atau menyerah / memaksa?"},
{n:42,type:"mcq",micro:"Skenario: kesepakatan dilanggar ketua",q:"Ketua timmu sendiri sering melanggar kesepakatan (telat, tidak mengabari). Sikap:",options:["Ingatkan dengan sopan & berdua: 'Kak, kita kan sepakat kabari kalau berhalangan. Ini bikin susah koordinasi.' — kesepakatan berlaku untuk semua","Diam saja karena dia ketua dan dianggap lebih tahu apa yang terbaik; anggota biasa tidak pantas menegur pemimpinnya","Ikut melanggar juga karena 'ketua saja melanggar', jadi tidak adil kalau hanya anggota biasa yang harus mematuhi kesepakatan"],answer:0,explain:"Kesepakatan kehilangan kekuatannya bila dikecualikan untuk ketua. Mengingatkan dengan hormat itu wajar.",hint:"Ingatkan sopan, atau diam / ikut melanggar?"},
{n:43,type:"mcq",micro:"Skenario: situasi darurat vs aturan",q:"Anggota tidak bisa ikut rapat wajib karena orang tuanya sakit mendadak. Sikap tim:",options:["Anggap dia berbohong karena tidak hadir, lalu catat sebagai pelanggaran di daftar tim dan beri tahu semua anggota","Ini pengecualian yang sah — jalankan prosedur yang disepakati (kabari sebelumnya, baca notulen), tunjukkan pengertian","Tetap hukum dia karena 'aturan adalah aturan', walaupun alasannya sudah dijelaskan dan dibenarkan oleh tim"],answer:1,explain:"Kesepakatan yang baik membedakan 'melanggar tanpa alasan' dari 'situasi darurat yang dikomunikasikan'. Yang kedua ditangani dengan empati.",hint:"Pengecualian sah dengan prosedur + empati, atau hukum tetap / curiga?"},
{n:44,type:"mcq",micro:"Skenario: kesepakatan tidak berjalan",q:"Kesepakatan 'rapat tiap hari' ternyata tidak realistis & sering batal. Langkah:",options:["Terus memaksakan rapat harian walaupun sering batal dan banyak yang kelelahan, karena kesepakatan harus ditaati","Berhenti rapat mulai sekarang tanpa pengganti, karena rapat harian terbukti tidak bisa dijalankan anggota","Bawa ke tim: 'Rapat harian kayaknya kebanyakan. Gimana kalau 2x seminggu + update chat harian?' — revisi bersama"],answer:2,explain:"Kesepakatan yang tidak berjalan direvisi bersama menjadi yang lebih realistis, bukan dipaksakan atau dibuang total.",hint:"Revisi bersama jadi realistis, atau paksakan / buang?"},
{n:45,type:"order",micro:"Merevisi kesepakatan tim",q:"Urutkan langkah merevisi kesepakatan tim yang tidak berjalan.",items:["Identifikasi bagian mana yang tidak berjalan & kenapa","Ajukan ke tim di rapat sebagai bahan diskusi, bukan keputusan sepihak","Bahas alternatif & sepakati versi baru yang lebih realistis","Perbarui catatan kesepakatan & pastikan semua tahu versi terbaru"],answer:[0,1,2,3],explain:"Identifikasi masalah → bawa ke tim → sepakati versi baru → perbarui & komunikasikan. Revisi tetap lewat kesepakatan.",hint:"Apa yang diidentifikasi sebelum membawa ke tim?"},
{n:46,type:"mcq",micro:"Skenario: anggota tidak tahu ada kesepakatan",q:"Seorang anggota melanggar aturan lalu berkata 'aku nggak tahu ada aturan itu'. Kemungkinan penyebab:",options:["Kesepakatan tidak ditulis, tidak dibagikan, atau dibuat saat ia tidak hadir — perbaiki dengan menuliskan & membagikan ke semua","Anggota itu berbohong untuk menghindari akibat dari kesalahannya, jadi sebaiknya langsung dihukum supaya yang lain tidak ikut-ikutan","Tidak perlu ditangani, karena alasan 'tidak tahu' itu hal biasa dan akan hilang seiring waktu berjalan"],answer:0,explain:"'Aku nggak tahu' sering menandakan kesepakatan tidak terdokumentasi atau tidak dikomunikasikan dengan baik. Perbaiki prosesnya.",hint:"Perbaiki dokumentasi & komunikasi, atau hukum / abaikan?"},
{n:47,type:"mcq",micro:"Skenario: dua anggota menafsirkan aturan berbeda",q:"Aturan 'bagian selesai sebelum tenggat internal' ditafsirkan satu orang sebagai 'draf kasar' & yang lain 'siap final'. Langkah:",options:["Salahkan anggota yang tafsirnya berbeda, lalu minta ia mengikuti caramu sendiri","Perjelas bersama arti 'selesai' & tuliskan definisinya, lalu terapkan untuk semua","Biarkan tiap anggota dengan tafsirnya sendiri, nanti di akhir baru dilihat mana yang benar"],answer:1,explain:"Aturan yang bisa ditafsir ganda perlu diperjelas definisinya bersama, bukan dibiarkan atau dijadikan bahan tuduhan.",hint:"Perjelas definisi bersama, atau biarkan / menyalahkan?"},
{n:48,type:"mcq",micro:"Skenario: kesepakatan soal privasi & data",q:"Timmu bekerja dengan data siswa (untuk proyek statistik). Kesepakatan yang perlu ditambahkan:",options:["Data bebas dibagikan kepada teman-teman di luar tim yang memintanya, selama dipakai untuk hal yang menarik","Tidak perlu aturan soal data, karena data siswa di sekolah biasanya aman dan jarang disalahgunakan","Data hanya dipakai untuk proyek, tidak disebarkan, nama disamarkan bila memungkinkan, & dihapus setelah selesai"],answer:2,explain:"Kesepakatan tim juga mencakup etika: cara memperlakukan informasi sensitif yang tim kelola.",hint:"Aturan pemakaian & privasi data, atau bebas / tanpa aturan?"},
{n:49,type:"mcq",micro:"Skenario: menegakkan kesepakatan tanpa jadi 'polisi'",q:"Cara mengingatkan anggota soal kesepakatan tanpa terkesan menghakimi:",options:["Rujuk ke kesepakatan bersama, bukan ke orangnya: 'Kita kan sepakat update tiap 2 hari — gimana progpecmu?' dengan nada ramah","'Kamu lagi-lagi melanggar aturan, padahal sudah berkali-kali diingatkan oleh anggota di tim ini, bukan?'","Diam saja dan menyimpan kesal, lalu menceritakannya ke anggota lain di belakang temanmu itu supaya mereka paham"],answer:0,explain:"Merujuk ke 'kesepakatan kita' (bukan 'kamu melanggar') membuat pengingatan terasa netral & tidak menyerang.",hint:"Rujuk ke kesepakatan bersama dengan ramah, atau menuduh / diam?"},
{n:50,type:"open",micro:"Skenario menyeluruh",q:"Kamu bergabung ke tim yang tidak punya kesepakatan apa pun & sudah mulai kacau di minggu pertama (info tercecer, tidak ada yang tahu tenggat, dua orang berkonflik soal keputusan). Sebagai anggota, rancang bagaimana kamu mengusulkan & membantu membuat kesepakatan tim sekarang (minimal 5 langkah).",explain:"Jawaban baik: usulkan pertemuan dengan nada solusi, datang dengan draf sebagai titik mulai, bahas tiap poin dengan masukan semua (terutama yang berkonflik) + sepakati mekanisme keputusan, fokus pada beberapa aturan inti yang jelas & realistis, tuliskan + konfirmasi tiap orang, sepakati peninjauan, dan menjaga penegakan dengan merujuk ke kesepakatan bukan menuding.",hint:"Ajak rapat singkat → bawa draf → bahas dengan masukan semua + selesaikan mekanisme konflik → beberapa aturan inti realistis → tulis + konfirmasi → sepakati tinjauan → jaga dengan merujuk kesepakatan.",sample:"(1) Usulkan pertemuan singkat dengan nada membantu: 'Kayaknya kita agak simpang siur. Yuk luangin 20 menit buat sepakati beberapa hal biar sisa proyek lebih lancar.' (2) Datang dengan draf usulan singkat (bukan aturan jadi), supaya diskusi punya titik mulai: poin soal komunikasi, tenggat, rapat, cara keputusan. (3) Di pertemuan, bahas tiap poin dan minta masukan tiap orang — terutama dua yang berkonflik, supaya mereka ikut memiliki. Untuk konflik keputusan mereka: sepakati mekanisme ke depan (dengar semua lalu voting/kompromi; mendesak diputuskan koordinator lalu dijelaskan). (4) Fokus pada beberapa aturan inti yang jelas dan realistis, bukan daftar panjang: cara & ritme komunikasi, tenggat internal + pembagian tugas tertulis, jadwal rapat singkat, aturan bila ada kendala, mekanisme keputusan, cara berinteraksi dengan hormat. (5) Tuliskan hasilnya di dokumen bersama, minta tiap orang konfirmasi 'setuju'. (6) Sepakati bahwa kesepakatan ini bisa ditinjau di titik tengah proyek. (7) Setelahnya, aku ikut menjaga dengan merujuk ke 'kesepakatan kita' secara ramah bila ada yang terlewat, bukan menuding. Aku menyampaikan semuanya sebagai usulan bersama, bukan mengambil alih."},
{n:51,type:"mcq",micro:"Skenario: kesepakatan soal kualitas",q:"Tim sering berdebat soal 'ini udah cukup bagus atau belum'. Kesepakatan yang membantu:",options:["Standar ditentukan oleh ketua secara sepihak di akhir proyek, setelah ia melihat hasil kerja seluruh anggota tim secara keseluruhan","Sepakati standar minimum yang konkret di awal (mis. 'tiap bagian: minimal 3 sumber, format sesuai template, dicek 1 anggota lain')","Serahkan saja pada perasaan masing-masing anggota apakah hasilnya sudah cukup bagus atau belum, tanpa perlu ukuran yang jelas"],answer:1,explain:"Standar kualitas yang disepakati di awal & konkret mencegah debat 'cukup atau belum' yang tak berujung.",hint:"Standar konkret disepakati di awal, atau perasaan / ketua sepihak?"},
{n:52,type:"tf",micro:"Kesepakatan butuh ditegakkan konsisten",q:"Benar atau Salah: Menegakkan kesepakatan hanya untuk sebagian anggota (mis. bukan teman ketua) tidak masalah, selama sebagian besar aturan tetap dipatuhi.",answer:false,explain:"Sebaliknya, penegakan yang pilih-pilih membuat anggota lain merasa aturan tidak adil & ikut mengabaikannya, sehingga seluruh kesepakatan cepat kehilangan kewibawaan.",hint:"Penegakan konsisten untuk semua, atau boleh pilih-pilih?"},
{n:53,type:"mcq",micro:"Skenario: kesepakatan menyeimbangkan beban",q:"Kesepakatan yang mencegah satu orang menanggung terlalu banyak:",options:["Serahkan pada anggota yang rela mengambil lebih banyak, karena mereka tidak keberatan dan tim tidak perlu repot membahasnya","Ketua menentukan beban tiap orang tanpa dicek lagi, karena ia lebih tahu dan anggota lain tidak perlu mempertanyakan","Setelah membagi tugas, tim mengecek bersama apakah beban tiap orang kira-kira sebanding & menyesuaikan bila tidak"],answer:2,explain:"Aturan 'cek keseimbangan beban setelah pembagian' membuat pembagian adil menjadi bagian dari proses, bukan kebetulan.",hint:"Cek keseimbangan bersama, atau 'yang rela' / ketua sepihak?"},
{n:54,type:"mcq",micro:"Skenario: kesepakatan & anggota pendiam",q:"Saat menyusun kesepakatan, anggota pendiam hanya diam & mengangguk. Sikap yang inklusif:",options:["Sengaja tanyakan pendapatnya: 'Menurutmu jadwal ini oke, [nama]? Ada yang mau kamu tambah?' — pastikan ia benar-benar setuju, bukan sekadar ikut","Anggap anggukannya sudah cukup sebagai tanda setuju, lalu langsung lanjut ke pembahasan berikutnya agar rapat tidak terlalu lama","Abaikan dia dan lanjutkan rapat, karena anggota pendiam biasanya akan mengikuti keputusan yang sudah dibuat oleh sebagian besar tim"],answer:0,explain:"Kesepakatan yang sah butuh persetujuan sadar semua, bukan diam yang mungkin berarti tidak enak menolak.",hint:"Tanyakan pendapatnya langsung, atau anggap anggukan cukup?"},
{n:55,type:"mcq",micro:"Skenario: kesepakatan lintas kelompok",q:"Timmu perlu berkoordinasi dengan tim lain (mis. panitia bidang berbeda). Kesepakatan antar-tim yang membantu:",options:["Tidak ada koordinasi antar-tim; masing-masing jalan sendiri dan baru bertemu di hari acara untuk melihat hasil","Satu penghubung tiap tim, jadwal koordinasi bersama, & kejelasan siapa bertanggung jawab atas area yang beririsan","Anggota kedua tim bebas saling menghubungi kapan saja lewat jalur apa saja, supaya informasi cepat tersebar"],answer:1,explain:"Koordinasi antar-tim butuh kesepakatan sendiri: titik kontak, jadwal, & kejelasan batas tanggung jawab.",hint:"Penghubung + jadwal + batas jelas, atau bebas / tanpa koordinasi?"},
{n:56,type:"mcq",micro:"Skenario: kesepakatan soal alat komunikasi",q:"Tim sepakat pakai grup chat A, tapi beberapa anggota malah membahas hal penting di japri & DM terpisah. Masalahnya:",options:["Tidak masalah selama beberapa orang yang terlibat sudah tahu keputusannya, karena yang penting pekerjaan berjalan & tidak perlu semua tahu","Buat lima grup chat baru untuk tiap topik pembicaraan, supaya setiap hal bisa dibahas terpisah dan tidak bercampur satu sama lain","Info jadi tercecer & sebagian anggota tidak tahu keputusan; ingatkan kesepakatan: hal proyek dibahas di grup utama"],answer:2,explain:"Kesepakatan 'satu kanal utama untuk hal proyek' hanya berguna bila ditegakkan; japri untuk hal proyek memecah informasi.",hint:"Info tercecer, ingatkan kesepakatan — atau tidak masalah / bikin grup baru?"},
{n:57,type:"tf",micro:"Kesepakatan bisa singkat",q:"Benar atau Salah: Agar efektif, kesepakatan tim harus panjang & mencakup sebanyak mungkin aturan detail untuk setiap kemungkinan.",answer:false,explain:"Sebaliknya, kualitas kesepakatan diukur dari kejelasan & apakah dipatuhi, bukan panjangnya. Beberapa poin inti yang jelas & disepakati sudah cukup untuk sebagian besar proyek.",hint:"Harus panjang & detail, atau beberapa poin inti cukup?"},
{n:58,type:"mcq",micro:"Skenario: menepati kesepakatan saat tidak diawasi",q:"Kamu bisa melanggar kesepakatan (mis. tidak mengabari kendala) tanpa ketahuan karena tidak ada yang mengawasi. Sikap yang berintegritas:",options:["Tetap tepati — kesepakatan adalah janji pada tim, bukan aturan yang hanya berlaku saat diawasi","Langgar saja karena tidak akan ketahuan, toh aturan itu hanya penting kalau ada yang mengawasi dan menilai","Tepati hanya kalau ketua sedang aktif memantau, karena kesepakatan baru penting saat ada yang menegur"],answer:0,explain:"Integritas adalah menepati kesepakatan meski tidak ada yang melihat. Itu yang membangun kepercayaan sejati.",hint:"Tepati karena itu janji, atau langgar karena tak ketahuan?"},
{n:59,type:"mcq",micro:"Skenario: kesepakatan untuk kegiatan berulang",q:"Untuk piket atau tugas rutin mingguan, kesepakatan yang adil:",options:["Orang-orang tertentu yang piket setiap kali, sedangkan sisanya lolos begitu saja karena sudah terbiasa sejak dulu","Jadwal rotasi tertulis + aturan menukar bila berhalangan (cari pengganti sendiri, kabari) + cara mencatat siapa sudah/belum","'Siapa yang ingat saja yang mengerjakan', tanpa jadwal atau catatan, sehingga tugas sering terlewat dan dikerjakan orang itu-itu saja"],answer:1,explain:"Kegiatan berulang butuh sistem rotasi tertulis & aturan pertukaran agar adil dari waktu ke waktu.",hint:"Rotasi tertulis + aturan tukar, atau 'siapa ingat' / tidak adil?"},
{n:60,type:"open",micro:"Menegakkan kesepakatan dengan adil",q:"Timmu punya kesepakatan tertulis. Di minggu kedua: anggota A telat tenggat 1 hari tapi mengabari sebelumnya dengan alasan jelas; anggota B telat 3 hari tanpa kabar sama sekali & tidak merespons chat. Jelaskan bagaimana tim sebaiknya menangani keduanya secara adil berdasarkan kesepakatan, dan mengapa keduanya diperlakukan berbeda.",explain:"Jawaban baik membedakan A (mematuhi aturan komunikasi meski telat — ditangani dengan pengertian & penyesuaian) dari B (melanggar aturan komunikasi + menghilang — ditangani berjenjang: hubungi pribadi → sampaikan dampak & tenggat baru → konsekuensi/eskalasi berbasis bukti), dan menjelaskan bahwa perbedaan perlakuan berdasar pada apakah kewajiban mengabari ditepati, bukan sekadar hasil telat.",hint:"Bedakan 'telat tapi mengabari jujur' (dimaklumi + bantu) dari 'menghilang tanpa kabar' (langkah berjenjang). Jelaskan bahwa yang dinilai adalah kepatuhan pada aturan komunikasi.",sample:"Anggota A: sudah menjalankan bagian dari kesepakatan yang benar — mengabari lebih awal dengan alasan jelas. Tim sebaiknya menunjukkan pengertian, membantu bila perlu (mis. anggota lain menutupi sebagian sementara), dan menyesuaikan jadwal kecil. Tidak perlu 'sanksi' karena A justru mematuhi aturan komunikasi; keterlambatan yang dikomunikasikan adalah hal yang wajar terjadi. Anggota B: melanggar dua hal sekaligus — telat dan tidak mengabari, lalu tidak merespons. Tim menjalankan langkah berjenjang sesuai kesepakatan: (1) coba hubungi B secara pribadi untuk memahami apakah ada masalah nyata (mungkin B dalam kesulitan). (2) Kalau B merespons: sampaikan dampaknya ke tim, sepakati tenggat baru + cek. (3) Kalau B tetap tidak merespons atau tidak bekerja: jalankan konsekuensi yang disepakati (mis. dibahas di tim, lalu disampaikan ke guru berdasarkan catatan pembagian tugas dan bukti chat). Keduanya diperlakukan berbeda karena kesepakatan tim membedakan 'keterlambatan yang dikomunikasikan dengan jujur' (dapat dimaklumi, ditangani dengan penyesuaian) dari 'menghilang tanpa kabar' (melanggar inti kesepakatan tentang komunikasi, ditangani berjenjang). Yang dinilai bukan hanya hasilnya telat, tapi apakah anggota menepati kewajiban mengabari."},
{n:61,type:"mcq",micro:"Mengapa kesepakatan di awal",q:"Mengapa menyepakati aturan tim di awal (bukan saat masalah muncul) lebih efektif?",options:["Tidak ada bedanya kapan aturan dibuat, sebab aturan akan ditaati sama baiknya di awal maupun saat masalah muncul","Aturan yang dibuat saat konflik jauh lebih adil, karena semua anggota sudah merasakan masalahnya dan tahu aturan yang dibutuhkan","Di awal semua tenang & objektif; saat konflik, emosi tinggi & tiap orang cenderung membuat aturan yang menguntungkan pihaknya"],answer:2,explain:"Kesepakatan di awal ibarat 'kontrak sosial' yang dibuat semua pihak sebelum tahu siapa akan diuntungkan/dirugikan — itu membuatnya lebih adil.",hint:"Awal = tenang & objektif, atau tak ada beda?"},
{n:62,type:"mcq",micro:"Mengapa aturan spesifik lebih baik",q:"Mengapa 'cek chat sekali sehari' mengalahkan 'jadi anggota yang responsif' sebagai aturan?",options:["Bisa disepakati bersama apakah dipenuhi atau tidak; 'responsif' bergantung tafsir & jadi bahan perdebatan","Lebih menyenangkan didengar dan terasa ramah, sehingga anggota lebih mudah menerimanya saat rapat","Lebih formal dan resmi, sehingga terlihat serius dan dihormati oleh anggota maupun oleh guru"],answer:0,explain:"Aturan yang tidak bisa diukur tidak bisa ditegakkan secara adil — hanya jadi alat saling menuduh.",hint:"Bisa diukur & disepakati, atau bergantung tafsir?"},
{n:63,type:"tf",micro:"Kesepakatan = rasa aman",q:"Benar atau Salah: Ketika semua anggota tahu 'aturan main' & tahu itu berlaku adil untuk semua, tim terasa lebih aman & orang lebih berani berkontribusi.",answer:true,explain:"Ketidakpastian ('apa yang boleh? apa yang terjadi kalau aku salah?') membuat orang berhati-hati & menahan diri. Kejelasan membebaskan.",hint:"Kesepakatan menambah rasa aman, atau tak berpengaruh?"},
{n:64,type:"mcq",micro:"Kesepakatan & penegakan",q:"Kesepakatan tanpa penegakan sama sekali cenderung...",options:["Menjadi lebih baik karena tim santai dan tidak tertekan oleh aturan, sehingga anggota bisa bekerja dengan lebih nyaman","Menjadi 'daftar harapan' yang diabaikan, & anggota yang mematuhinya merasa bodoh karena yang melanggar tidak kena apa-apa","Tetap efektif karena anggota akan patuh dengan sendirinya, tanpa tindak lanjut ketika ada yang melanggar"],answer:1,explain:"Kesepakatan yang tidak pernah ditegakkan mengajarkan bahwa melanggar tidak berkonsekuensi — yang lain ikut melanggar.",hint:"Jadi daftar harapan yang diabaikan, atau tetap efektif?"},
{n:65,type:"mcq",micro:"Kesepakatan & fleksibilitas",q:"Kesepakatan tim yang baik tegas soal prinsip inti TAPI...",options:["Kaku tanpa pengecualian, termasuk untuk hal kecil dan keadaan darurat, supaya anggota disiplin","Longgar sampai tidak berarti lagi, bahkan untuk prinsip inti seperti saling menghormati","Fleksibel soal detail & punya prosedur untuk situasi tak terduga (darurat, perubahan)"],answer:2,explain:"Tegas + manusiawi: aturan inti dipegang, tapi ada jalan untuk situasi sah yang tak terduga.",hint:"Tegas prinsip + fleksibel detail, atau kaku total / longgar total?"},
{n:66,type:"tf",micro:"Kesepakatan bisa direvisi kapan saja oleh siapa saja?",q:"Benar atau Salah: Setiap anggota boleh mengubah kesepakatan tim kapan saja secara sepihak bila menurutnya perlu.",answer:false,explain:"Sebaliknya, revisi kesepakatan harus lewat proses yang sama seperti membuatnya: dibahas & disetujui tim. Perubahan sepihak menghancurkan kepercayaan pada kesepakatan.",hint:"Sepihak kapan saja, atau lewat kesepakatan tim lagi?"},
{n:67,type:"mcq",micro:"Mengapa kesepakatan mengurangi 'drama'",q:"Bagaimana kesepakatan yang jelas mengurangi drama & pertengkaran dalam tim?",options:["Banyak konflik lahir dari ekspektasi yang berbeda & tidak diucapkan; kesepakatan membuat ekspektasi eksplisit & sama untuk semua","Karena anggota jadi takut kepada ketua dan tidak berani berbeda pendapat, sehingga pertengkaran tidak terjadi di tim","Kesepakatan tidak memengaruhi konflik, sebab konflik datang dari sifat pribadi anggota dan tidak berhubungan dengan aturan"],answer:0,explain:"'Kukira kamu tahu itu bagianmu' & 'kukira kita nggak wajib rapat' adalah bahan bakar pertengkaran yang dipadamkan kesepakatan.",hint:"Menyamakan ekspektasi, atau membuat takut?"},
{n:68,type:"mcq",micro:"Kesepakatan & keadilan prosedural",q:"Anggota lebih menerima konsekuensi (mis. kontribusinya dicatat rendah) bila...",options:["Hanya dia yang dikenai konsekuensi, sedangkan anggota lain yang melakukan hal serupa dibiarkan begitu saja tanpa diingatkan apa-apa","Aturannya jelas sejak awal, berlaku sama untuk semua, & ia diberi kesempatan menjelaskan — bukan hukuman mendadak","Konsekuensi diputuskan diam-diam di akhir proyek oleh ketua, lalu diumumkan begitu saja tanpa ada penjelasan atau kesempatan membela diri"],answer:1,explain:"'Keadilan prosedural': orang menerima hasil yang tidak menyenangkan bila prosesnya dianggap adil & transparan.",hint:"Aturan jelas di awal + berlaku sama + ada kesempatan menjelaskan, atau mendadak / pilih-pilih?"},
{n:69,type:"mcq",micro:"Kesepakatan sebagai pelindung",q:"Kesepakatan tim yang adil terutama melindungi...",options:["Hanya ketua, karena dialah yang paling berwenang dan paling banyak menanggung tanggung jawab di tim","Anggota yang paling vokal, karena mereka paling sering menyuarakan kebutuhan dan kepentingan tim","Anggota yang lebih lemah posisinya (pendiam, baru, kurang PD) dari didominasi atau dibebani tidak adil"],answer:2,explain:"Tanpa aturan, tim cenderung berjalan menurut kehendak yang paling keras. Kesepakatan menyeimbangkan itu.",hint:"Melindungi yang posisinya lemah, atau menguntungkan yang vokal?"},
{n:70,type:"order",micro:"Dari tim tanpa aturan ke tim berkesepakatan",q:"Urutkan proses membawa tim yang kacau menuju punya kesepakatan yang berfungsi.",items:["Tunjukkan gejala kekacauan sebagai alasan (info tercecer, tenggat tidak jelas)","Ajak tim luangkan waktu singkat menyusun beberapa aturan inti bersama","Tuliskan kesepakatan & minta semua menyetujui secara sadar","Tinjau di titik tengah: apa yang berjalan, apa yang perlu direvisi"],answer:[0,1,2,3],explain:"Tunjukkan kebutuhan → susun bersama → tulis & setujui → tinjau. Kesepakatan tumbuh dari kebutuhan nyata, bukan formalitas.",hint:"Apa yang ditunjukkan sebagai alasan sebelum menyusun aturan?"},
{n:71,type:"mcq",micro:"Kesepakatan & budaya tim",q:"Setelah beberapa proyek, tim yang terbiasa membuat & menepati kesepakatan cenderung...",options:["Membangun 'budaya' saling percaya & efisien, di mana kesepakatan jadi kebiasaan alami","Sering bertengkar soal aturan saat memulai proyek baru, karena tiap orang merasa aturannya benar","Tidak berubah dari proyek pertama, sebab membuat kesepakatan tidak memengaruhi cara kerja tim"],answer:0,explain:"Kesepakatan yang berulang ditepati menjadi norma tak tertulis — tim tidak perlu lagi banyak membahasnya.",hint:"Budaya percaya & efisien, atau bertengkar terus?"},
{n:72,type:"tf",micro:"Menepati kesepakatan membangun reputasi",q:"Benar atau Salah: Seseorang yang secara konsisten menepati kesepakatan tim membangun reputasi sebagai orang yang bisa diandalkan, yang berguna jauh melampaui satu proyek.",answer:true,explain:"Reputasi 'kalau dia bilang akan, dia akan' membuat orang ingin bekerja denganmu & memberimu tanggung jawab lebih besar.",hint:"Membangun reputasi andal, atau tak berpengaruh?"},
{n:73,type:"mcq",micro:"Kesepakatan & konteks berbeda",q:"Kesepakatan yang cocok untuk tim proyek sekolah 2 minggu...",options:["Tidak perlu disesuaikan, karena semua tim punya kebutuhan yang serupa dan aturan sama bisa dipakai di mana saja","Belum tentu cocok untuk tim olahraga, panitia acara besar, atau organisasi jangka panjang — sesuaikan dengan konteks","Cocok untuk semua jenis tim tanpa perubahan, termasuk tim olahraga & panitia acara besar yang bekerja berbulan-bulan lamanya"],answer:1,explain:"Prinsipnya sama (buat bersama, jelas, adil, tegakkan), tapi isinya menyesuaikan durasi, ukuran, & jenis tim.",hint:"Sesuaikan dengan konteks, atau satu template untuk semua?"},
{n:74,type:"mcq",micro:"Menilai kesepakatan yang baik",q:"Tanda sebuah kesepakatan tim berfungsi baik:",options:["Anggota jarang membacanya lagi setelah dibuat dan ditempel, sehingga isinya hanya diingat samar-samar oleh beberapa orang","Hanya ketua yang tahu isinya secara lengkap, sedangkan anggota lain cukup mengikuti perintah ketua","Anggota merujuk padanya saat ada keraguan, konflik lebih cepat selesai, sedikit 'kukira kamu', & terasa adil bagi semua"],answer:2,explain:"Kesepakatan yang 'hidup' dipakai sebagai acuan sehari-hari, bukan dokumen yang dilupakan.",hint:"Dipakai sebagai acuan & terasa adil, atau dilupakan?"},
{n:75,type:"tf",micro:"Kesepakatan mengikat ketua juga",q:"Benar atau Salah: Bila ketua tim melanggar kesepakatan yang ia sendiri ikut buat, ia merusak kewibawaan seluruh kesepakatan & memberi 'izin' tidak langsung bagi anggota lain untuk melanggar juga.",answer:true,explain:"Pemimpin adalah contoh. Kesepakatan yang tidak berlaku untuk pemimpin cepat runtuh untuk semua.",hint:"Ketua melanggar = merusak semua, atau tak berpengaruh?"},
{n:76,type:"mcq",micro:"Kesepakatan & efisiensi",q:"Meski membuat kesepakatan butuh waktu di awal, ia menghemat waktu keseluruhan karena...",options:["Mengurangi kebingungan berulang, pertengkaran, & kerja ulang yang muncul dari ekspektasi yang tidak jelas","Tidak menghemat waktu; kesepakatan hanya menambah pekerjaan di awal dan tidak berpengaruh pada tahap berikutnya","Membuat keputusan lebih lambat, karena setiap langkah harus diperiksa dulu dengan aturan yang sudah ditulis"],answer:0,explain:"15-20 menit di awal sering menghemat berjam-jam kekacauan & konflik nanti — investasi yang sangat menguntungkan.",hint:"Menghemat waktu keseluruhan, atau memperlambat?"},
{n:77,type:"mcq",micro:"Kesepakatan & anggota yang tidak setuju sejak awal",q:"Seorang anggota tidak setuju dengan sebuah aturan sejak penyusunan. Sikap tim yang adil:",options:["Batalkan aturan itu karena satu orang tidak setuju, sebab kesepakatan baru sah bila seluruh anggota tanpa kecuali menyetujuinya, dan keberatan itu tidak perlu dibahas lagi","Dengarkan keberatannya, cari kompromi bila bisa; kalau tim tetap memilih aturan itu, ia tetap terikat karena mayoritas sepakat & prosesnya adil — tapi keberatannya dicatat","Abaikan keberatannya dan jangan dicatat, karena yang kalah suara tidak berhak mengungkitnya lagi selama proyek berjalan, sehingga anggota lain tidak perlu mengetahuinya"],answer:1,explain:"Kesepakatan tidak selalu berarti bulat; yang penting semua didengar & prosesnya adil, lalu semua terikat pada hasil.",hint:"Dengar + kompromi + terikat hasil adil, atau abaikan / batalkan?"},
{n:78,type:"mcq",micro:"Kesepakatan soal apa yang TIDAK dilakukan",q:"Kesepakatan tim juga bisa menyebut hal yang dilarang, misalnya...",options:["Tidak boleh berbeda pendapat dari ketua atau mayoritas, karena perbedaan dianggap mengganggu kekompakan dan memperlambat kerja","Tidak boleh bertanya tentang tugas yang tidak dimengerti, karena bertanya dianggap membuang waktu dan menunjukkan kelemahan","Tidak menyebarkan masalah tim ke luar (gosip), tidak mengambil alih bagian orang tanpa bilang, tidak menghina saat diskusi"],answer:2,explain:"Larangan yang jelas (anti-gosip, anti-ambil alih diam-diam, anti-hina) melindungi kepercayaan & rasa aman tim.",hint:"Larangan yang melindungi kepercayaan, atau melarang pendapat / bertanya?"},
{n:79,type:"mcq",micro:"Kesepakatan & pembelajaran tim",q:"Meninjau kesepakatan setelah proyek ('mana yang berjalan, mana yang tidak') berguna karena...",options:["Tim membawa pelajaran ke proyek berikutnya & kesepakatan berikutnya jadi lebih baik","Membuang waktu karena proyek sudah selesai dan hasilnya sudah dikumpulkan","Membuat anggota saling menyalahkan, sehingga hubungan di dalam tim menjadi lebih buruk"],answer:0,explain:"Kesepakatan yang dievaluasi berkembang. Tim yang sama jadi makin efektif tiap proyek.",hint:"Membawa pelajaran ke depan, atau buang waktu?"},
{n:80,type:"open",micro:"Menganalisis dua pendekatan",q:"Tim A: langsung kerja, tidak ada kesepakatan, 'nanti kalau ada masalah baru dibahas'. Tim B: menghabiskan 20 menit di awal menyusun kesepakatan tertulis (komunikasi, tenggat, rapat, keputusan, kendala), lalu meninjaunya di tengah. Jelaskan mengapa Tim B kemungkinan mengalami lebih sedikit konflik & kerja ulang (minimal 4 alasan), dan 1 kondisi di mana Tim A mungkin baik-baik saja.",explain:"Jawaban baik memberi minimal 4 alasan Tim B unggul (ekspektasi eksplisit & seragam, tenggat internal + tugas tertulis = masalah dini, mekanisme keputusan mencegah konflik prosedur, aturan kendala mencegah ledakan akhir, peninjauan tengah memperbaiki dini) dan 1 kondisi Tim A bisa baik (tim sangat kecil + sudah sering kerja sama + tugas sederhana + semua komunikatif & andal).",hint:"Alasan B unggul: ekspektasi seragam, tenggat internal, mekanisme keputusan, aturan kendala, tinjauan tengah. Kondisi A oke: tim kecil, sudah biasa bersama, tugas sederhana.",sample:"Tim B kemungkinan lebih sedikit konflik & kerja ulang karena: (1) Ekspektasi dibuat eksplisit & sama untuk semua sejak awal, jadi lebih sedikit 'kukira kamu yang kerjakan' atau 'kukira kita nggak wajib rapat'. (2) Ada tenggat internal & pembagian tugas tertulis, jadi masalah ketahuan lebih awal dan tidak menumpuk di akhir. (3) Ada mekanisme keputusan yang disepakati, jadi saat ada perbedaan pendapat tim tinggal menjalankan prosedur, bukan bertengkar soal cara memutuskan. (4) Ada aturan bila ada kendala (wajib mengabari), jadi keterlambatan bisa dibantu, bukan meledak mendadak. (5) Peninjauan di tengah membuat aturan yang tidak berjalan diperbaiki sebelum menimbulkan kerusakan. Tim A menyelesaikan konflik hanya SETELAH terjadi — saat emosi sudah tinggi dan sebagian pekerjaan mungkin sudah salah arah. Kondisi di mana Tim A mungkin baik-baik saja: bila timnya sangat kecil (2 orang), sudah sering bekerja sama sehingga sudah punya 'kesepakatan tak tertulis' dari kebiasaan, tugasnya sederhana & pendek, dan keduanya sama-sama komunikatif serta andal. Dalam kondisi itu, biaya membuat kesepakatan formal mungkin melebihi manfaatnya — tapi ini pengecualian, bukan aturan umum."},
{n:81,type:"mcq",micro:"Kasus: kesepakatan diuji krisis",q:"Di tengah proyek, terjadi krisis (satu anggota keluar, tenggat dimajukan). Peran kesepakatan tim saat krisis:",options:["Kesepakatan harus dibuang saat krisis dan tim bebas bertindak sesuka hati, karena situasi darurat tidak bisa diatur","Menjadi acuan yang menstabilkan: prosedur menangani perubahan sudah ada, jadi tim tinggal menjalankannya dengan tenang","Kesepakatan jadi tidak relevan saat krisis karena dibuat untuk keadaan biasa, jadi tim sebaiknya menunggu arahan guru"],answer:1,explain:"Kesepakatan yang mengantisipasi perubahan ('bila situasi berubah, tim rapat menyesuaikan pembagian & tenggat') justru paling berharga saat krisis.",hint:"Acuan yang menstabilkan, atau tidak relevan saat krisis?"},
{n:82,type:"mcq",micro:"Kasus: kesepakatan bertentangan dengan aturan sekolah/guru",q:"Tim ingin menyepakati sesuatu yang bertentangan dengan aturan tugas dari guru (mis. 'boleh saling menyalin bagian'). Sikap:",options:["Kesepakatan tim lebih kuat daripada aturan guru, karena anggota tim yang paling tahu cara kerja yang cocok","Abaikan aturan guru diam-diam dan jalankan kesepakatan tim, asalkan seluruh anggota setuju dan tidak dilaporkan","Kesepakatan tim tidak boleh melanggar aturan yang lebih tinggi (guru, sekolah, hukum, etika); sesuaikan"],answer:2,explain:"Kesepakatan internal tim beroperasi di dalam batas aturan yang lebih besar & etika. Tidak bisa dipakai untuk membenarkan pelanggaran.",hint:"Di dalam batas aturan yang lebih tinggi, atau mengalahkannya?"},
{n:83,type:"tf",micro:"Refleksi: kesepakatan = fondasi kerja sama",q:"Benar atau Salah: Membuat kesepakatan bersama hanya berguna untuk tugas sekolah; di organisasi & dunia kerja semua sudah diatur atasan sehingga keterampilan ini tidak relevan.",answer:false,explain:"Sebaliknya, hampir setiap tim yang berfungsi baik punya bentuk kesepakatan — eksplisit atau dari kebiasaan. Membuat, menepati, & meninjaunya adalah keterampilan kolaborasi mendasar yang berlaku seumur hidup.",hint:"Keterampilan mendasar seumur hidup, atau hanya untuk tugas sekolah?"},
{n:84,type:"mcq",micro:"Kasus: mayoritas menekan minoritas lewat 'kesepakatan'",q:"Mayoritas tim ingin menyepakati aturan yang jelas merugikan satu anggota (mis. 'dia yang selalu bikin notulen & bersih-bersih'). Sikap adil:",options:["Kesepakatan harus adil, bukan sekadar suara terbanyak; aturan yang membebani satu orang tidak proporsional bukan kesepakatan yang sehat — cari pembagian yang seimbang","Mayoritas menang dan aturan itu sah, karena kesepakatan memang ditentukan oleh suara terbanyak tanpa mempertimbangkan perasaan anggota, sehingga yang keberatan cukup menyesuaikan diri","Anggota itu harus menerima karena sudah kalah suara, dan tidak berhak mengeluh karena prosesnya sudah lewat pemungutan suara yang sah, apalagi bila hasilnya sudah dicatat di notulen"],answer:0,explain:"Suara terbanyak tidak otomatis membuat sesuatu adil. Kesepakatan yang baik menyeimbangkan efisiensi & keadilan bagi semua.",hint:"Kesepakatan harus adil, atau mayoritas selalu menang?"},
{n:85,type:"order",micro:"Menyusun kesepakatan untuk organisasi jangka panjang",q:"Urutkan langkah menyusun kesepakatan untuk klub/organisasi yang berjalan setahun (bukan proyek pendek).",items:["Sepakati tujuan & nilai organisasi bersama seluruh anggota","Sepakati struktur: peran, cara pengambilan keputusan, cara memilih pengurus","Sepakati aturan operasional: rapat, komunikasi, tanggung jawab, penanganan konflik","Sepakati cara meninjau & merevisi kesepakatan secara berkala"],answer:[0,1,2,3],explain:"Tujuan & nilai → struktur → aturan operasional → mekanisme revisi. Organisasi jangka panjang butuh fondasi yang lebih dalam daripada proyek pendek.",hint:"Apa yang disepakati paling dasar sebelum struktur & aturan operasional?"},
{n:86,type:"mcq",micro:"Kasus: kesepakatan yang tidak pernah ditegakkan",q:"Timmu punya kesepakatan bagus di kertas, tapi tidak ada yang pernah menegakkannya & semua melanggar. Langkah:",options:["Menyerah pada kesepakatan itu dan bekerja tanpa aturan, karena terbukti anggota tidak mau menjalankannya dengan baik dalam tim, lalu membahasnya lagi nanti","Bahas di tim: apakah kesepakatannya tidak realistis (revisi), atau kita perlu benar-benar berkomitmen menegakkannya (mulai dari sekarang, konsisten untuk semua)?","Buat kesepakatan baru yang lebih panjang dan rinci tanpa membahas mengapa yang lama dilanggar, supaya terlihat ada perubahan"],answer:1,explain:"Kesepakatan yang tidak ditegakkan butuh diagnosis: masalahnya di aturannya (revisi) atau di komitmen (mulai tegakkan konsisten)?",hint:"Diagnosis: revisi atau komitmen menegakkan — atau bikin baru yang panjang / menyerah?"},
{n:87,type:"tf",micro:"Kesepakatan melindungi hubungan",q:"Benar atau Salah: Kesepakatan yang jelas sebenarnya melindungi pertemanan dalam tim, karena mengurangi kesalahpahaman & kekecewaan yang bisa merusak hubungan.",answer:true,explain:"Banyak pertemanan retak karena kerja kelompok yang kacau. Kesepakatan yang jelas mengurangi gesekan itu.",hint:"Melindungi hubungan, atau merusak keakraban?"},
{n:88,type:"mcq",micro:"Kasus: kamu satu-satunya yang ingin kesepakatan",q:"Kamu ingin tim membuat kesepakatan, tapi semua anggota lain malas & menolak. Sikap:",options:["Menyerah dan tidak membahasnya lagi, karena anggota yang menolak berarti tidak membutuhkan kesepakatan tertulis, lalu bekerja sendiri-sendiri saja","Memaksa dengan marah dan mengancam akan melapor ke guru, supaya anggota yang menolak akhirnya mau ikut membuat aturan, walau suasana tim jadi tegang","Buat versi sangat singkat (3 poin) & bingkai sebagai 'biar nggak ribet nanti'; kalau tetap ditolak, setidaknya perjelas siapa-apa-kapan lewat chat & rujuk itu bila ada masalah"],answer:2,explain:"Kalau kesepakatan formal ditolak, minimal ciptakan kejelasan praktis (pembagian tertulis) yang bisa kamu rujuk saat masalah muncul.",hint:"Versi minimal / kejelasan praktis, atau menyerah / memaksa?"},
{n:89,type:"mcq",micro:"Kasus: kesepakatan & anggota dari budaya berbeda",q:"Anggota timmu dari latar/budaya berbeda punya kebiasaan berbeda soal ketepatan waktu & cara bicara. Peran kesepakatan:",options:["Membuat ekspektasi eksplisit & disepakati semua, sehingga tidak ada yang 'melanggar norma yang tidak pernah diucapkan' — semua tahu standar yang sama","Memaksakan norma dari satu budaya sebagai yang paling benar bagi anggota, lalu menganggap yang berbeda sebagai pelanggaran, walau norma itu belum dibahas bersama","Tidak membahasnya dan berharap anggota otomatis punya kebiasaan yang sama, karena sudah berada di kelompok yang sama, sehingga perbedaan dibiarkan muncul sendiri"],answer:0,explain:"Kesepakatan eksplisit menggantikan 'norma tak tertulis' yang berbeda antar orang dengan standar yang disepakati bersama.",hint:"Ekspektasi eksplisit yang disepakati semua, atau paksakan satu norma / diam?"},
{n:90,type:"open",micro:"Kasus menyeluruh",q:"Kamu terpilih jadi ketua panitia acara sekolah dengan 10 anggota, durasi 5 minggu. Rancang bagaimana kamu memfasilitasi tim membuat kesepakatan yang: dibuat bersama (bukan kamu paksakan), jelas & realistis, adil untuk semua termasuk yang pendiam, dan benar-benar ditegakkan. Minimal 6 langkah konkret dengan alasan.",explain:"Jawaban baik memuat minimal 6 langkah konkret dengan alasan: bingkai sebagai penghemat waktu, bawa topik bukan aturan jadi, fasilitasi dengan giliran/kelompok kecil untuk melibatkan yang pendiam, uji kerealistisan untuk semua situasi, aturan spesifik & terukur & sedikit, tulis + persetujuan sadar tiap orang, ketua menepati lebih dulu, tegakkan konsisten & adil dengan merujuk kesepakatan, tinjau di tengah.",hint:"Fasilitasi (bukan paksakan): topik bukan aturan jadi, giliran/kelompok kecil untuk yang pendiam, uji realistis untuk semua, aturan spesifik & sedikit, persetujuan sadar tertulis, ketua jadi contoh, tegakkan adil, tinjau di tengah.",sample:"(1) Di pertemuan pertama, jelaskan tujuannya: 'Kita luangin 30 menit buat sepakati cara kerja bareng, biar sisa 5 minggu lebih lancar.' — bingkai sebagai penghemat waktu, bukan birokrasi. (2) Bawa daftar TOPIK yang perlu disepakati (komunikasi, rapat, pembagian tugas & tenggat, cara keputusan, aturan kendala, cara berinteraksi, konsekuensi pelanggaran), tapi BUKAN aturan jadi — biar tim mengisinya bersama. (3) Bahas tiap topik dengan meminta usulan dari anggota; untuk memastikan yang pendiam ikut, aku putar giliran ('menurut kamu gimana?') dan pecah jadi diskusi kelompok kecil dulu sebelum pleno. (4) Untuk tiap aturan, uji: 'Apakah ini realistis untuk semua? Ada yang situasinya bikin susah mematuhi ini?' — sesuaikan bila ada yang tidak bisa (mis. yang tidak punya internet di rumah). (5) Sepakati aturan yang SPESIFIK & TERUKUR (bukan 'rajin' tapi 'cek chat 1x sehari'), dan batasi jumlahnya ke yang inti. (6) Tuliskan hasilnya di dokumen bersama, baca ulang bareng, minta tiap orang mengetik 'setuju' — persetujuan sadar, bukan diam. (7) Sebagai ketua, aku berkomitmen menepatinya lebih dulu (datang tepat waktu, mengabari bila berhalangan) — karena tim meniru pemimpin. (8) Tegakkan konsisten & adil: bila ada yang terlewat, aku merujuk ke 'kesepakatan kita' dengan ramah, sama untuk semua termasuk teman dekatku. (9) Tinjau kesepakatan di akhir minggu ke-2: apa yang berjalan, apa yang perlu direvisi bersama."},
{n:91,type:"mcq",micro:"Kasus: kesepakatan vs semangat spontan",q:"Seorang anggota berkata kesepakatan 'membunuh spontanitas & kreativitas tim'. Tanggapan seimbang:",options:["Buat aturan yang mengatur juga isi ide dan cara berpikir tiap anggota, supaya kreativitas tim terarah dan tidak keluar jalur dari rencana awal, sehingga tim tetap rapi","Kesepakatan mengatur PROSES (komunikasi, tenggat, keputusan) supaya tim bisa fokus berkreasi tanpa kekacauan — ia justru memberi ruang aman untuk spontan di dalam kerja","Setuju saja dan buang semua kesepakatan, karena kreativitas hanya bisa muncul bila tim bebas dari batasan aturan, walaupun kerja sama jadi makin sulit"],answer:1,explain:"Kesepakatan yang baik menstruktur proses, bukan mengekang isi/ide. Struktur proses justru membebaskan energi untuk hal kreatif.",hint:"Mengatur proses supaya bisa fokus berkreasi, atau membunuh kreativitas?"},
{n:92,type:"tf",micro:"Refleksi: kesepakatan dibuat, ditepati, ditinjau",q:"Benar atau Salah: Siklus sehat sebuah kesepakatan tim adalah: dibuat bersama di awal, ditepati & ditegakkan selama proyek, lalu ditinjau untuk pelajaran di akhir.",answer:true,explain:"Ketiga tahap itu membuat kesepakatan menjadi alat yang hidup & terus membaik, bukan dokumen sekali pakai.",hint:"Buat-tepati-tinjau, atau sekali buat lalu lupa?"},
{n:93,type:"mcq",micro:"Kasus: kesepakatan & keputusan yang tidak kamu suka",q:"Tim, lewat mekanisme yang disepakati, memutuskan hal yang tidak kamu suka. Sikap yang konsisten dengan kesepakatan:",options:["Menyabotase keputusan itu diam-diam karena aku tidak menyukainya, supaya terbukti bahwa pilihanku sebenarnya jauh lebih baik dari mereka","Menuntut keputusan itu dibatalkan & diulang sampai sesuai dengan keinginanku, walaupun mekanisme yang kami sepakati sudah dijalankan dengan adil","Karena aku ikut menyepakati mekanismenya & prosesnya adil, aku mendukung keputusan itu & memberi yang terbaik — sambil boleh mencatat keberatanku"],answer:2,explain:"Menyepakati mekanisme berarti menerima hasilnya meski bukan pilihanmu ('disagree and commit'), selama prosesnya adil.",hint:"Dukung hasil dari proses adil, atau sabotase / tuntut batal?"},
{n:94,type:"mcq",micro:"Kasus: menegakkan tanpa merusak hubungan",q:"Kamu perlu menegur teman yang melanggar kesepakatan berulang. Cara menjaga hubungan:",options:["Berdua, tenang, rujuk ke kesepakatan bersama (bukan menyerang pribadi), tanyakan kendalanya, & sepakati langkah — sambil tegaskan ini penting untuk tim","Menegur dengan keras di depan seluruh tim supaya ia malu dan jera, serta anggota lain ikut belajar dari kejadian itu sekaligus","Diam & membiarkan pelanggaran berlanjut demi menjaga pertemanan, karena menegur teman dianggap bisa merusak hubungan yang sudah baik selama ini"],answer:0,explain:"Menegakkan kesepakatan & menjaga hubungan bisa berjalan bersama: privat, berbasis kesepakatan, mencari solusi, tetap tegas.",hint:"Privat + berbasis kesepakatan + cari solusi, atau keras di depan tim / diam?"},
{n:95,type:"tf",micro:"Kesepakatan bukan jaminan, tapi fondasi",q:"Benar atau Salah: Kesepakatan tim menjamin tim akan berhasil; kalau sebuah tim gagal, itu pasti karena kesepakatannya kurang lengkap.",answer:false,explain:"Sebaliknya, kesepakatan adalah fondasi yang menaikkan peluang keberhasilan, bukan jaminan. Tetap butuh anggota yang menepatinya; tim tanpa kesepakatan apa pun jauh lebih rentan kacau & penuh konflik.",hint:"Fondasi yang menaikkan peluang, atau jaminan?"},
{n:96,type:"mcq",micro:"Kasus: refleksi tentang kesepakatan",q:"Cara melatih keterampilan membuat kesepakatan tim lewat refleksi:",options:["Tidak mengevaluasi kesepakatan setelah proyek berakhir, karena yang penting hasil sudah dikumpulkan dan tidak perlu dibahas lagi","Setelah tiap proyek: apakah kami punya kesepakatan? apakah jelas & adil? apakah ditepati? bagian mana yang perlu diubah lain kali?","Menyimpulkan kesepakatan tidak berguna bila proyek gagal, sehingga proyek berikutnya dikerjakan tanpa kesepakatan dahulu"],answer:1,explain:"Meninjau bagaimana kesepakatan berjalan mengubah tiap proyek menjadi pelajaran untuk kolaborasi berikutnya.",hint:"Evaluasi kesepakatan tiap proyek, atau tak pernah / menyimpulkan tak berguna?"},
{n:97,type:"mcq",micro:"Prinsip inti bab ini",q:"Pesan inti kesepakatan & aturan bersama:",options:["Ketua menulis semua aturan sendiri lalu memberitahukan kepada anggota, buat sebanyak mungkin aturan agar rinci, dan hukum yang melanggar tanpa kecuali, walau alasannya masuk akal dan tim jadi tegang","Jangan bikin aturan, langsung kerja dan bahas masalah kalau muncul nanti, karena kesepakatan di awal hanya membuang waktu dan membuat tim kaku, sehingga anggota bebas berbeda cara kerja masing-masing","Buat kesepakatan bersama di awal (saat tenang), aturan yang spesifik-realistis-adil-sedikit, tuliskan & setujui semua, tegakkan konsisten untuk semua termasuk ketua, sisakan ruang untuk situasi tak terduga, & tinjau berkala"],answer:2,explain:"Ringkasan: dibuat bersama + spesifik/realistis/adil/sedikit + tertulis & disetujui + ditegakkan konsisten + fleksibel untuk pengecualian sah + ditinjau.",hint:"Bersama, spesifik-realistis-adil-sedikit, tertulis, konsisten, fleksibel, ditinjau — rangkai."},
{n:98,type:"tf",micro:"Refleksi: kesepakatan melayani tim & tiap orang",q:"Benar atau Salah: Kesepakatan tim yang baik menguntungkan tim (koordinasi & lebih sedikit konflik) DAN tiap anggota (kejelasan ekspektasi, perlindungan dari beban tidak adil, & rasa aman).",answer:true,explain:"Kesepakatan yang hanya menguntungkan 'tim' dengan mengorbankan individu tertentu bukan kesepakatan yang sehat.",hint:"Untung tim & tiap orang, atau tim saja?"},
{n:99,type:"mcq",micro:"Kasus: memulai kebiasaan berkesepakatan",q:"Cara termudah mulai membiasakan kesepakatan tim di kelompok berikutnya:",options:["Di pertemuan pertama, usulkan 15 menit untuk menyepakati & menuliskan 4-5 hal: komunikasi, pembagian tugas + tenggat, rapat, cara keputusan, aturan kendala","Menunggu sampai bertemu tim yang lebih terorganisasi dan punya ketua berpengalaman, baru kemudian memikirkan kesepakatan secara serius bersama mereka","Membiarkan kesepakatan terbentuk sendiri secara alami seiring proyek berjalan, tanpa dibahas, ditulis, atau disetujui anggota di awal, karena tim akan saling memahami"],answer:0,explain:"Kebiasaan dimulai dari satu tindakan: mengusulkan & memfasilitasi 15 menit penyusunan kesepakatan di setiap kelompok baru.",hint:"Usulkan 15 menit menyepakati beberapa hal inti, atau menunggu / membiarkan?"},
{n:100,type:"open",micro:"Refleksi & aturan pribadi soal kesepakatan tim",q:"Tulis 'aturan pribadi tentang kesepakatan & aturan bersama dalam tim' berisi minimal 5 poin yang akan kamu pegang, masing-masing dengan alasan singkat.",explain:"Jawaban baik memuat minimal 5 aturan konkret dengan alasan, mencakup ide inti bab: usulkan & susun kesepakatan di awal, buat spesifik-realistis-adil-sedikit, pastikan persetujuan sadar semua (termasuk pendiam), tepati meski tak diawasi, revisi lewat tim bukan sepihak, tegakkan dengan merujuk kesepakatan & konsisten untuk semua, tinjau setelah proyek.",hint:"Ambil satu pelajaran tiap fase — susun di awal, spesifik & adil, persetujuan sadar semua, tepati tanpa diawasi, revisi lewat tim, tegakkan adil, tinjau — jadikan aturan 'aku akan...'.",sample:"Contoh aturan pribadi: (1) Di awal setiap kerja kelompok, aku mengusulkan meluangkan 15 menit untuk menyepakati & menuliskan cara kerja bersama (komunikasi, pembagian tugas + tenggat, rapat, cara keputusan, aturan kendala) — karena menyepakati saat tenang jauh lebih mudah daripada saat konflik. (2) Aku memastikan aturannya spesifik & terukur ('cek chat 1x sehari'), realistis untuk semua situasi anggota, adil, dan sedikit — karena aturan kabur atau mustahil hanya jadi bahan tuduhan. (3) Aku memastikan semua anggota, terutama yang pendiam, benar-benar menyetujui secara sadar — bukan sekadar diam mengangguk. (4) Aku menepati kesepakatan meski tidak ada yang mengawasi — karena itu janji pada tim, bukan aturan yang hanya berlaku saat dilihat. (5) Bila sebuah aturan ternyata tidak berjalan, aku membawanya ke tim untuk direvisi bersama, bukan mengabaikannya sepihak. (6) Saat mengingatkan anggota, aku merujuk ke 'kesepakatan kita' dengan ramah, bukan menyerang pribadi, dan berlaku sama untuk semua termasuk teman dekatku. (7) Setelah proyek, aku ikut meninjau: apa yang berjalan, apa yang perlu diubah untuk kesepakatan berikutnya."},
];
